def list_assistants(status=None, limit=None, cursor=None, sort_by=None, sort_order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0109000" if __import__("os").path.isdir("./environment_mix/0109000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_iso_z(s):
        if not isinstance(s, str):
            return None
        try:
            # Normalize Z and timezone offsets
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(ok, error_obj=None):
        # Must not break API if logging fails.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "request_id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": "list_assistants",
                "timestamp": _now(),
                "latency_ms": int((time.time() - t0) * 1000),
                "status": "ok" if ok else "error",
                "error_code": None if ok else (error_obj.get("error", {}) or {}).get("code"),
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None
        rpm = cfg.get("requests_per_minute")
        if not (isinstance(rpm, int) and rpm > 0):
            return None
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        cutoff = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc) - datetime.timedelta(seconds=60)
        cnt = 0
        for r in logs:
            ts = r.get("timestamp")
            dt = _parse_iso_z(ts)
            if not dt:
                continue
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            if dt >= cutoff:
                cnt += 1
        if cnt >= rpm:
            return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    # Enforce rate limit (logged as an error)
    rl = _rate_limit_check()
    if rl:
        _log(False, rl)
        return rl

    # Validate inputs
    allowed_status = {"draft", "active", "disabled", "archived"}
    if status is not None:
        if not isinstance(status, str):
            e = _err("VALIDATION_ERROR", "status must be a string", field="status")
            _log(False, e)
            return e
        if status not in allowed_status:
            e = _err("VALIDATION_ERROR", "status must be one of: draft, active, disabled, archived", field="status")
            _log(False, e)
            return e

    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        e = _err("VALIDATION_ERROR", "limit must be an integer", field="limit")
        _log(False, e)
        return e
    if limit < 1 or limit > 100:
        e = _err("VALIDATION_ERROR", "limit must be between 1 and 100", field="limit")
        _log(False, e)
        return e

    allowed_sort_by = {"created_at", "updated_at", "display_name"}
    if sort_by is None:
        sort_by = "updated_at"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        e = _err("VALIDATION_ERROR", "sort_by must be one of: created_at, updated_at, display_name", field="sort_by")
        _log(False, e)
        return e

    allowed_sort_order = {"asc", "desc"}
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        e = _err("VALIDATION_ERROR", "sort_order must be one of: asc, desc", field="sort_order")
        _log(False, e)
        return e

    if cursor is not None and not isinstance(cursor, str):
        e = _err("VALIDATION_ERROR", "cursor must be a string", field="cursor")
        _log(False, e)
        return e

    data = _load("assistants.json")
    if isinstance(data, dict) and isinstance(data.get("rows"), list):
        rows = data["rows"]
    elif isinstance(data, list):
        rows = data
    else:
        rows = []

    # Business rule: list_assistants returns assistants where status != 'archived' (unless explicitly filtered by status='archived')
    filtered = []
    for r in rows:
        if not isinstance(r, dict):
            continue
        st = r.get("status")
        if status is None:
            if st == "archived":
                continue
        else:
            if st != status:
                continue
        filtered.append(r)

    # Sorting
    def _key(r):
        if sort_by in ("created_at", "updated_at"):
            dt = _parse_iso_z(r.get(sort_by))
            # Put unparseable at the end consistently
            if not dt:
                dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc) if sort_order == "asc" else datetime.datetime(9999, 1, 1, tzinfo=datetime.timezone.utc)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        if sort_by == "display_name":
            v = r.get("display_name")
            return v.lower() if isinstance(v, str) else ""
        return ""

    reverse = (sort_order == "desc")
    try:
        filtered.sort(key=_key, reverse=reverse)
    except Exception:
        # If any weird types slip through, fall back to stable ordering by assistant_id
        filtered.sort(key=lambda r: (str(r.get("assistant_id") or "")), reverse=reverse)

    # Cursor semantics: treat cursor as the last seen assistant_id from previous page.
    # Must be "opaque" and not strictly validated; if it doesn't match anything, return empty page (not an error).
    start_index = 0
    if cursor:
        idx = None
        for i, r in enumerate(filtered):
            if r.get("assistant_id") == cursor:
                idx = i
                break
        if idx is None:
            # Relaxed behavior: unknown cursor yields empty result page (no error)
            start_index = len(filtered)
        else:
            start_index = idx + 1

    page = filtered[start_index:start_index + limit]
    has_more = (start_index + limit) < len(filtered)
    next_cursor = page[-1].get("assistant_id") if (has_more and page) else None

    resp = {
        "data": page,
        "meta": {
            "total": len(filtered),
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
        }
    }
    _log(True, None)
    return resp

def create_assistant(display_name, voice_config, model_config, description=None, webhook_url=None, status=None, **_extra):
    import json, os, datetime, time, base64, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0109000" if __import__("os").path.isdir("./environment_mix/0109000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _load_rows(filename):
        data = _load(filename)
        if isinstance(data, dict) and isinstance(data.get("rows"), list):
            return data["rows"], data, "dict"
        if isinstance(data, list):
            return data, None, "list"
        return [], None, "unknown"

    def _save_rows(filename, rows, container, kind):
        if kind == "dict" and isinstance(container, dict):
            container["rows"] = rows
            _save(filename, container)
        else:
            _save(filename, rows)

    def _append_log(status_code, error_code=None):
        logs, logs_container, logs_kind = _load_rows("request_logs.json")
        entry = {
            "request_id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
            "endpoint": "create_assistant",
            "timestamp": _now(),
            "latency_ms": int((time.time() - t0) * 1000),
            "status": int(status_code) if isinstance(status_code, int) else status_code,
            "error_code": error_code,
        }
        logs.append(entry)
        _save_rows("request_logs.json", logs, logs_container, logs_kind)

    def _enforce_limits():
        cfg = _load("service_limits.json")
        if not isinstance(cfg, dict):
            return None

        logs, _, _ = _load_rows("request_logs.json")
        now = datetime.datetime.utcnow()

        rpm = cfg.get("requests_per_minute")
        if isinstance(rpm, int) and rpm > 0:
            window_start = now - datetime.timedelta(minutes=1)
            recent = 0
            for l in logs:
                ts = _parse_ts(l.get("timestamp"))
                if ts is not None and ts >= window_start:
                    recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded (requests_per_minute).", rule="requests_per_minute", limit=rpm)

        daily = cfg.get("requests_per_day")
        if isinstance(daily, int) and daily > 0:
            window_start = now - datetime.timedelta(days=1)
            recent = 0
            for l in logs:
                ts = _parse_ts(l.get("timestamp"))
                if ts is not None and ts >= window_start:
                    recent += 1
            if recent >= daily:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded (requests_per_day).", rule="requests_per_day", limit=daily)

        return None

    # Enforce rate/quota based on persisted request logs, then continue.
    limit_err = _enforce_limits()
    if limit_err:
        _append_log(429, limit_err["error"]["code"])
        return limit_err

    # Validate required fields/types.
    if not isinstance(display_name, str) or not display_name.strip():
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "display_name is required and must be a non-empty string.", field="display_name")
    if not isinstance(voice_config, dict):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "voice_config must be an object.", field="voice_config")
    if not isinstance(model_config, dict):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model_config must be an object.", field="model_config")
    if description is not None and not isinstance(description, str):
        _append_log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "description must be a string or null.", field="description")
    if webhook_url is not None:
        if not isinstance(webhook_url, str):
            _append_log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook_url must be a string or null.", field="webhook_url")
        if webhook_url != "" and not webhook_url.startswith("https://"):
            _append_log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook_url must start with 'https://'.", field="webhook_url", rule="webhook_url like 'https://%'")
    allowed_status = {"draft", "active", "disabled", "archived"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: draft, active, disabled, archived.", field="status", allowed=sorted(list(allowed_status)))

    # Business rule: create_assistant inserts a new assistants row with status='draft' and version=1.
    # Even if caller provides status, the backend behavior is to initialize as draft.
    init_status = "draft"

    # Load existing assistants, enforce uniqueness by display_name (exact match).
    assistants, assistants_container, assistants_kind = _load_rows("assistants.json")
    dn = display_name.strip()

    for a in assistants:
        if isinstance(a, dict) and a.get("display_name") == dn:
            # If this exists, it's a real conflict.
            _append_log(409, "CONFLICT")
            return _err(
                "CONFLICT",
                "display_name must be unique (constraint unique(display_name)).",
                field="display_name",
                rule="unique(display_name)"
            )

    # Generate assistant_id (avoid collisions).
    def _gen_id(prefix, rows, pk):
        for _ in range(25):
            candidate = prefix + base64.urlsafe_b64encode(os.urandom(9)).decode("ascii").rstrip("=")
            if not any(isinstance(r, dict) and r.get(pk) == candidate for r in rows):
                return candidate
        return None

    assistant_id = _gen_id("asst_", assistants, "assistant_id")
    if assistant_id is None:
        _append_log(500, "CONFLICT")
        return _err("CONFLICT", "Unable to allocate unique assistant_id.", rule="id_generation")

    now = _now()
    row = {
        "assistant_id": assistant_id,
        "display_name": dn,
        "description": description if description is not None else None,
        "voice_config": voice_config,
        "model_config": model_config,
        "webhook_url": webhook_url if webhook_url is not None else None,
        "status": init_status,
        "version": 1,
        "created_at": now,
        "updated_at": now,
    }

    assistants.append(row)
    _save_rows("assistants.json", assistants, assistants_container, assistants_kind)

    _append_log(201, None)
    return {"assistant": row}

def get_assistant(assistant_id, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0109000" if __import__("os").path.isdir("./environment_mix/0109000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code_local, error=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "request_id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": "get_assistant",
                "timestamp": _now(),
                "latency_ms": int((time.time() - t0) * 1000),
                "status": "error" if status_code_local != "ok" else "ok",
                "error_code": None if not error else error.get("code"),
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        if isinstance(cfg, dict):
            rpm = cfg.get("requests_per_minute")
            if isinstance(rpm, int) and rpm > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str):
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                if cnt >= rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"])
        return rl

    if not isinstance(assistant_id, str):
        e = _err("VALIDATION_ERROR", "assistant_id must be a string", field="assistant_id")
        _log("VALIDATION_ERROR", e["error"])
        return e

    if not re.match(r"^vapi_asst_[0-9A-Z]{18,}$", assistant_id):
        e = _err("VALIDATION_ERROR", "assistant_id is malformed", field="assistant_id")
        _log("VALIDATION_ERROR", e["error"])
        return e

    assistants = _load("assistants.json")
    if not isinstance(assistants, list):
        assistants = []

    for a in assistants:
        if isinstance(a, dict) and a.get("assistant_id") == assistant_id:
            _log("ok")
            return {"data": a}

    e = _err("NOT_FOUND", "Assistant not found", assistant_id=assistant_id)
    _log("NOT_FOUND", e["error"])
    return e

def update_assistant(assistant_id, display_name=None, description=None, voice_config=None, model_config=None, webhook_url=None, status=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0109000" if __import__("os").path.isdir("./environment_mix/0109000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_code_local, error=None):
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            row = {
                "request_id": "req_" + base64.urlsafe_b64encode(os.urandom(12)).decode("ascii").rstrip("="),
                "endpoint": "update_assistant",
                "timestamp": _now(),
                "latency_ms": int((time.time() - t0) * 1000),
                "status": "error" if status_code_local != "ok" else "ok",
                "error_code": None if not error else error.get("code"),
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _rate_limit_check():
        cfg = _load("service_limits.json")
        if isinstance(cfg, dict):
            rpm = cfg.get("requests_per_minute")
            if isinstance(rpm, int) and rpm > 0:
                logs = _load("request_logs.json")
                if not isinstance(logs, list):
                    return None
                cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
                cnt = 0
                for r in logs:
                    ts = r.get("timestamp")
                    if isinstance(ts, str):
                        try:
                            dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                        except Exception:
                            continue
                        if dt >= cutoff:
                            cnt += 1
                if cnt >= rpm:
                    return _err("RATE_LIMIT", "Rate limit exceeded")
        return None

    rl = _rate_limit_check()
    if rl:
        _log("RATE_LIMIT", rl["error"])
        return rl

    if not isinstance(assistant_id, str):
        e = _err("VALIDATION_ERROR", "assistant_id must be a string", field="assistant_id")
        _log("VALIDATION_ERROR", e["error"])
        return e
    if not re.match(r"^vapi_asst_[0-9A-Z]{18,}$", assistant_id):
        e = _err("VALIDATION_ERROR", "assistant_id is malformed", field="assistant_id")
        _log("VALIDATION_ERROR", e["error"])
        return e

    if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
        e = _err("VALIDATION_ERROR", "display_name must be a non-empty string", field="display_name")
        _log("VALIDATION_ERROR", e["error"])
        return e
    if isinstance(display_name, str):
        display_name = display_name.strip()

    if description is not None and not isinstance(description, str):
        e = _err("VALIDATION_ERROR", "description must be a string", field="description")
        _log("VALIDATION_ERROR", e["error"])
        return e

    if voice_config is not None and not isinstance(voice_config, dict):
        e = _err("VALIDATION_ERROR", "voice_config must be an object", field="voice_config")
        _log("VALIDATION_ERROR", e["error"])
        return e

    if model_config is not None and not isinstance(model_config, dict):
        e = _err("VALIDATION_ERROR", "model_config must be an object", field="model_config")
        _log("VALIDATION_ERROR", e["error"])
        return e

    if webhook_url is not None:
        if not isinstance(webhook_url, str):
            e = _err("VALIDATION_ERROR", "webhook_url must be a string", field="webhook_url")
            _log("VALIDATION_ERROR", e["error"])
            return e
        if webhook_url != "" and not webhook_url.startswith("https://"):
            e = _err("VALIDATION_ERROR", "webhook_url must start with 'https://'", field="webhook_url")
            _log("VALIDATION_ERROR", e["error"])
            return e

    allowed_status = {"draft", "active", "disabled", "archived"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        e = _err("VALIDATION_ERROR", "Invalid status", field="status")
        _log("VALIDATION_ERROR", e["error"])
        return e

    assistants = _load("assistants.json")
    if not isinstance(assistants, list):
        assistants = []

    idx = None
    for i, a in enumerate(assistants):
        if isinstance(a, dict) and a.get("assistant_id") == assistant_id:
            idx = i
            break
    if idx is None:
        e = _err("NOT_FOUND", "Assistant not found", assistant_id=assistant_id)
        _log("NOT_FOUND", e["error"])
        return e

    current = assistants[idx]
    if not isinstance(current, dict):
        e = _err("CONFLICT", "Corrupt assistant record", assistant_id=assistant_id)
        _log("CONFLICT", e["error"])
        return e

    # unique(display_name)
    if display_name is not None and display_name != current.get("display_name"):
        for a in assistants:
            if isinstance(a, dict) and a.get("display_name") == display_name and a.get("assistant_id") != assistant_id:
                e = _err("CONFLICT", "display_name must be unique", field="display_name")
                _log("CONFLICT", e["error"])
                return e

    # Status transition enforcement
    transitions = {
        "draft": {"active", "archived"},
        "active": {"disabled", "archived"},
        "disabled": {"active", "archived"},
        "archived": set()
    }
    if status is not None:
        cur_status = current.get("status")
        if cur_status not in transitions:
            e = _err("CONFLICT", "Assistant has invalid current status", current_status=cur_status)
            _log("CONFLICT", e["error"])
            return e
        if status != cur_status:
            if status not in transitions[cur_status]:
                e = _err("INVALID_TRANSITION", "Illegal status transition", from_status=cur_status, to_status=status)
                _log("INVALID_TRANSITION", e["error"])
                return e

    # Apply updates
    changed = False
    if display_name is not None:
        current["display_name"] = display_name
        changed = True
    if description is not None:
        current["description"] = description
        changed = True
    if voice_config is not None:
        current["voice_config"] = voice_config
        changed = True
    if model_config is not None:
        current["model_config"] = model_config
        changed = True
    if webhook_url is not None:
        current["webhook_url"] = webhook_url
        changed = True
    if status is not None and status != current.get("status"):
        current["status"] = status
        changed = True

    if not changed:
        # Still a mutation call; real APIs typically return current resource. But "no success without effect"
        # applies to matched-no-row; here we matched a row. Return current without changing version.
        _log("ok")
        return {"data": current}

    # version increment and timestamps
    v = current.get("version")
    if not isinstance(v, int) or v < 1:
        v = 1
    current["version"] = v + 1
    current["updated_at"] = _now()
