            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if err:
            row["error"] = err
        if extra and isinstance(extra, dict):
            row.update(extra)
        logs.append(row)
        _save("request_logs.json", logs)

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or not cur:
            return None
        try:
            pad = "=" * (-len(cur) % 4)
            raw = base64.urlsafe_b64decode((cur + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("offset:"):
                return None
            off = int(raw.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except (ValueError, UnicodeDecodeError, base64.binascii.Error):
            return None

    def _make_cursor(off):
        raw = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _dt_key(v):
        if v is None:
            return None
        if isinstance(v, str):
            s = v
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                return datetime.datetime.fromisoformat(s)
            except ValueError:
                return None
        return None

    # Validate inputs
    try:
        if assistant_id is not None:
            if not isinstance(assistant_id, str) or not re.match(r"^vapi_asst_[0-9A-Z]{18,}$", assistant_id):
                _log(400, {"code": "VALIDATION_ERROR", "message": "assistant_id is invalid"})
                return _err("VALIDATION_ERROR", "assistant_id is invalid")
        if from_phone_number_id is not None:
            if not isinstance(from_phone_number_id, str) or not re.match(r"^vapi_pn_[0-9A-Z]{18,}$", from_phone_number_id):
                _log(400, {"code": "VALIDATION_ERROR", "message": "from_phone_number_id is invalid"})
                return _err("VALIDATION_ERROR", "from_phone_number_id is invalid")
        if to_e164 is not None:
            if not isinstance(to_e164, str) or not to_e164.startswith("+") or len(to_e164) < 2:
                _log(400, {"code": "VALIDATION_ERROR", "message": "to_e164 must be a valid E.164 string"})
                return _err("VALIDATION_ERROR", "to_e164 must be a valid E.164 string")
        if status is not None:
            if not isinstance(status, str) or status not in ("queued", "dialing", "in_progress", "completed", "failed", "canceled"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "status is invalid"})
                return _err("VALIDATION_ERROR", "status is invalid")
        if limit is None:
            limit_v = 20
        else:
            if not isinstance(limit, int):
                _log(400, {"code": "VALIDATION_ERROR", "message": "limit must be an integer"})
                return _err("VALIDATION_ERROR", "limit must be an integer")
            if limit < 1 or limit > 100:
                _log(400, {"code": "VALIDATION_ERROR", "message": "limit out of range"})
                return _err("VALIDATION_ERROR", "limit out of range")
            limit_v = limit
        if sort_by is None:
            sort_by_v = "created_at"
        else:
            if not isinstance(sort_by, str) or sort_by not in ("created_at", "updated_at", "started_at", "ended_at"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "sort_by is invalid"})
                return _err("VALIDATION_ERROR", "sort_by is invalid")
            sort_by_v = sort_by
        if sort_order is None:
            sort_order_v = "desc"
        else:
            if not isinstance(sort_order, str) or sort_order not in ("asc", "desc"):
                _log(400, {"code": "VALIDATION_ERROR", "message": "sort_order is invalid"})
                return _err("VALIDATION_ERROR", "sort_order is invalid")
            sort_order_v = sort_order

        offset = _parse_cursor(cursor)
        if offset is None:
            _log(400, {"code": "VALIDATION_ERROR", "message": "cursor is invalid"})
            return _err("VALIDATION_ERROR", "cursor is invalid")
    except Exception as e:
        _log(500, {"code": "VALIDATION_ERROR", "message": "invalid parameters"})
        return _err("VALIDATION_ERROR", "invalid parameters")

    calls = _load("calls.json")
    if not isinstance(calls, list):
        calls = []

    # Filter
    filtered = []
    for c in calls:
        if not isinstance(c, dict):
            continue
        if assistant_id is not None and c.get("assistant_id") != assistant_id:
            continue
        if from_phone_number_id is not None and c.get("from_phone_number_id") != from_phone_number_id:
            continue
        if to_e164 is not None and c.get("to_e164") != to_e164:
            continue
        if status is not None and c.get("status") != status:
            continue
        filtered.append(c)

    # Sort
    reverse = (sort_order_v == "desc")

    def _sort_key(c):
        v = c.get(sort_by_v)
        dt = _dt_key(v)
        # None values: place last in asc, first in desc? Most APIs place nulls last; do that.
        null_rank = 1 if dt is None else 0
        if reverse:
            null_rank = -null_rank  # keep nulls last even when reverse by flipping rank
        # Secondary sort stable by call_id
        return (null_rank, dt if dt is not None else datetime.datetime.min, c.get("call_id") or "")

    # To keep nulls last in both orders, we sort twice: compute key without reverse and handle reverse manually.
    # Simpler: sort with reverse on dt, but also keep nulls last.
    def _sort_key2(c):
        dt = _dt_key(c.get(sort_by_v))
        null_rank = 1 if dt is None else 0
        cid = c.get("call_id") or ""
        return (null_rank, dt if dt is not None else datetime.datetime.min, cid)

    filtered.sort(key=_sort_key2, reverse=reverse)
    total = len(filtered)

    page = filtered[offset:offset + limit_v]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _make_cursor(next_off) if has_more else None

    resp = {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit_v,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "sort_by": sort_by_v,
            "sort_order": sort_order_v,
        }
    }
    _log(200, extra={"result_count": len(page), "total": total})
    return resp

