        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "list_tools"

    def _log(status_code, credential_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        ts = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        logs = _load("request_logs.json")
        row = {
            "request_log_id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": ts,
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _rate_limited():
        logs = _load("request_logs.json")
        now = datetime.datetime.utcnow()
        per_min = 120
        per_day = 10000
        m = 0
        d = 0
        for r in logs:
            ts = r.get("created_at")
            if not isinstance(ts, str):
                continue
            try:
                rt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
            except Exception:
                continue
            delta = now - rt
            if delta.total_seconds() <= 60:
                m += 1
            if delta.total_seconds() <= 86400:
                d += 1
        if m >= per_min:
            return ("RATE_LIMIT", f"Rate limit exceeded: {per_min}/minute.")
        if d >= per_day:
            return ("QUOTA_EXCEEDED", f"Daily quota exceeded: {per_day}/day.")
        return None

    rl = _rate_limited()
    if rl:
        code, msg = rl
        _log(429, error_code=code)
        return _err(code, msg)

    # --- validation ---
    if integration_type is not None:
        if not isinstance(integration_type, str) or integration_type not in ("builtin", "webhook", "mcp"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "integration_type is invalid.", field="integration_type")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "deprecated", "disabled"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status is invalid.", field="status")
    if slug is not None and not isinstance(slug, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "slug must be a string.", field="slug")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit out of range (1-100).", field="limit")
    if cursor is not None and not isinstance(cursor, str):
        _log(400, error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
    if sort is not None:
        if not isinstance(sort, str) or sort not in ("created_at", "updated_at", "display_name", "slug"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
    if order is not None:
        if not isinstance(order, str) or order not in ("asc", "desc"):
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "order is invalid.", field="order")

    tools = _load("tools.json")
    rows = [r for r in tools if isinstance(r, dict)]

    # Business rule: list_tools returns tools where status in ('active','deprecated')
    rows = [r for r in rows if r.get("status") in ("active", "deprecated")]

    # Additional filters
    if integration_type is not None:
        rows = [r for r in rows if r.get("integration_type") == integration_type]
    if status is not None:
        # allow filtering to disabled even though default list excludes; but business rule says list_tools returns only active/deprecated
        # so filtering to disabled yields empty.
        rows = [r for r in rows if r.get("status") == status]
    if slug is not None:
        rows = [r for r in rows if r.get("slug") == slug]

    # Sorting: default display_name asc per business rule
    if sort is None:
        sort = "display_name"
    if order is None:
        order = "asc"

    def _key(v):
        x = v.get(sort)
        if x is None:
            return ""
        return x

    rev = (order == "desc")
    try:
        rows.sort(key=_key, reverse=rev)
    except TypeError:
        # Mixed types; coerce to string
        rows.sort(key=lambda r: str(r.get(sort, "")), reverse=rev)

    # Cursor: opaque base64 of integer offset
    offset = 0
    if cursor:
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            offset = int(raw.decode("utf-8"))
            if offset < 0:
                raise ValueError()
        except Exception:
            _log(400, error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    total = len(rows)
    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(str(next_offset).encode("utf-8")).decode("utf-8").rstrip("=")

    _log(200)
    return {
        "tools": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

